with flagged as (select *, case when txn_time - lag(txn_time) over (partition by account_id order by txn_time asc, id asc) > interval '60' day then 1 else 0 end as session_start_flag from transactions) select id, account_id, txn_time, is_flagged, sum(session_start_flag) over (partition by account_id order by txn_time asc, id asc rows between unbounded preceding and current row) as session_id from flagged
